// ===== v7: kursi & sofa pengantin di pelaminan (3 aset PNG terpisah) =====
const PEL={"kiri": ["data:image/webp;base64,", 526, 651], "sofa": ["data:image/webp;base64,", 952, 685], "kanan": ["data:image/webp;base64,", 527, 651]},PCV={};
function pc(k){if(PCV[k])return PCV[k];const d=PEL[k],c=cvs(d[1],d[2],()=>{}),im=new Image();im.onload=()=>{c.getContext('2d').drawImage(im,0,0);if(c.t)c.t.needsUpdate=true};im.src=d[0];return PCV[k]=c}
Object.keys(PEL).forEach(pc);
const _rl7=relayout;relayout=function(id,x,z,w,y){const o=LAYOUT.find(o=>o.id==id);if(!o||!o.p)return _rl7(id,x,z,w,y);const s=VS[id];if(!s)return;if(x!=null)o.x=x;if(z!=null)o.z=z;if(w!=null)o.w=w;if(y!=null)o.y=y;const c=pc(o.k);s.position.set(o.x,o.y||0,o.z);s.scale.set(o.w,o.w*c.height/c.width,1)};
const _ill7=illustrate;
illustrate=function(){const r=_ill7();VL.pelaminan=new THREE.Group();VL.pelaminan.name='pelaminan';sc.add(VL.pelaminan);
 [['pel-kiri','kiri',-5.4,-38.9,3.7],['pel-kanan','kanan',5.4,-38.9,3.7],['pel-sofa','sofa',0,-39.4,7.4]].forEach(([id,k,x,z,w])=>{const o={id,k,x,z,w,y:1.35,l:'pelaminan',p:1};LAYOUT.push(o);const s=spr(pc(k),1,1,0,0,0);s.userData.area='stage';clk.push(s);VS[id]=s;VL.pelaminan.add(s);relayout(id,x,z,w,1.35)});
 coupleEnts().forEach((e,i)=>{e.g.scale.setScalar(1.45);e.g.position.set(i?1.2:-1.2,1.35,-35.8);e.ly=4.0});
 return r};
